import local.cleartv.mobile.*;import java.net.*;import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;
public class DownloadCheck{
 static byte[] read(InputStream in)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}
 public static void main(String[] args)throws Exception{byte[] apk=Files.readAllBytes(Paths.get(args[0]));try(LanHttp server=new LanHttp(18788,(method,path,headers,body)->ApkDownload.response(apk,method,path,headers))){URL url=new URL("http://127.0.0.1:18788/tv-morph.apk");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setRequestMethod("HEAD");if(c.getResponseCode()!=200||c.getContentLength()!=apk.length||c.getInputStream().read()!=-1)throw new Exception("HEAD failed");c.disconnect();c=(HttpURLConnection)url.openConnection();c.setRequestProperty("Range","bytes=20-119");if(c.getResponseCode()!=206||!Arrays.equals(Arrays.copyOfRange(apk,20,120),read(c.getInputStream())))throw new Exception("Range failed");c.disconnect();c=(HttpURLConnection)url.openConnection();if(!Arrays.equals(MessageDigest.getInstance("SHA-256").digest(apk),MessageDigest.getInstance("SHA-256").digest(read(c.getInputStream()))))throw new Exception("APK mismatch");c.disconnect();System.out.println("PASS: APK HEAD length/no body, byte-range resume and full-file SHA-256 match.");}}
}
